GimCorpus.put(525,0,[[1,2,"כיצד המתכוין לומר הרי זה תמורת עולה וכו'. עיין במ\"ש רש\"י פ\"ה דנזיר (דף ל\"ב) שכתב ה\"מ דסבור לומר תמורת עולה ואמר תמורת שלמים אבל אם הפריש בהמה לצורך תמורת עולה וחזר ואמר הרי זה תמורת שלמים כיון דהפרישה ושוב טעה איגלאי מילתא דלאו שפיר המיר ולא הויא תמורה ודברים אלו תמוהים הם בעיני. ועיין במ\"ש התוס' שם (דף ל\"ג) שפירש פירוש אחר באותה סוגיא ודבריהם מתיישבים היטב בפירוש ההלכה:",1,0],[2,3,"היו לפניו שלש בהמות קדשי מזבח וכו'. (א\"ה עיין במ\"ש הרב המחבר בפרק י' מהלכות גירושין הלכה י\"ח):",1,0],[2,4,"האומר הרי זה תמורת עולה כו'. עיין בתויו\"ט פ\"ז דדמאי משנה ו' ודוק: אע\"פ שחזר בתוך כ\"ד כו'. עיין בר\"פ ט\"ו מהל' מעשה הקרבנות, ועי' בש\"ך ח\"מ סי' ר\"ה ס\"ק ה':",1,0],[3,2,"ותמורת המעשר לבעלים. תמורת מעשר הוי כמעשר למיקם עליה בלא ימכר ובלא יגאל פ\"ק דזבחים (דף ט') יע\"ש: סליקו להו הלכות תמורה בס\"ד",1,0]]);
